<div class="flex flex-col lg:flex-row justify-between gap-3 mb-5"><form method="GET" data-qf-auto-filter class="card p-4 grid grid-cols-1 sm:grid-cols-4 gap-3 flex-1 items-center"><input class="input" name="search" value="<?php echo e(request('search')); ?>" placeholder="Name, email or student ID" autocomplete="off"><select class="input" name="role"><option value="">All roles</option><?php $__currentLoopData = ['admin','staff','student']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $role): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($role); ?>" <?php if(request('role')===$role): echo 'selected'; endif; ?>><?php echo e(ucfirst($role)); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><select class="input" name="status"><option value="">All statuses</option><option value="active" <?php if(request('status')==='active'): echo 'selected'; endif; ?>>Active</option><option value="inactive" <?php if(request('status')==='inactive'): echo 'selected'; endif; ?>>Blocked</option></select><span class="qf-auto-filter-status" role="status" aria-live="polite"><span class="qf-auto-filter-spinner" aria-hidden="true"></span><span data-qf-filter-status>Updating…</span></span></form><a href="<?php echo e(route('admin.users.create')); ?>" class="btn-primary self-start">+ Add User</a></div>
