$loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="7" class="text-center text-slate-500 py-10">No accounts found.</td></tr><?php endif; ?></tbody></table></div><div class="p-4"><?php echo e($users->links('vendor.pagination.queueflow')); ?></div></div>
